import { randomUUID } from "node:crypto";
import http from "node:http";
import type { AddressInfo } from "node:net";

/** Only the bundled server knows this launch's return address; browsers cannot trigger it. */
export async function startAuthReturn(onReturn: (path: string) => Promise<void>) {
  const token = randomUUID();
  const server = http.createServer(async (req, res) => {
    if (req.method !== "POST" || req.url !== `/${token}` || req.headers.origin) {
      res.writeHead(403).end(); return;
    }
    const path = req.headers["x-moneo-return"];
    if (typeof path !== "string" || !/^\/import\?(bank|scalable)=(connected|error|invalid)(#scalable)?$/.test(path)) {
      res.writeHead(400).end(); return;
    }
    try { await onReturn(path); res.writeHead(204).end(); }
    catch { res.writeHead(503).end(); }
  });
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });
  return {
    url: `http://127.0.0.1:${(server.address() as AddressInfo).port}/${token}`,
    close: () => { server.close(); server.closeAllConnections(); },
  };
}
import { expect, it, vi } from "vitest";
import { startAuthReturn } from "./auth-return";

it("returns only authenticated, fixed connection destinations to the app", async () => {
  const open = vi.fn(async () => {});
  const bridge = await startAuthReturn(open);
  try {
    expect((await fetch(bridge.url)).status).toBe(403);
    expect((await fetch(bridge.url, { method: "POST", headers: { origin: "https://example.com", "x-moneo-return": "/import?bank=connected" } })).status).toBe(403);
    expect((await fetch(bridge.url, { method: "POST", headers: { "x-moneo-return": "https://example.com" } })).status).toBe(400);
    expect(open).not.toHaveBeenCalled();
    expect((await fetch(bridge.url, { method: "POST", headers: { "x-moneo-return": "/import?scalable=connected#scalable" } })).status).toBe(204);
    expect(open).toHaveBeenCalledWith("/import?scalable=connected#scalable");
  } finally { bridge.close(); }
});
import { NextResponse } from "next/server";

/** Complete browser consent in the desktop window when its private return bridge is available. */
export async function connectionReturn(request: Request, path: string) {
  const bridge = process.env.MONEO_DESKTOP_AUTH_RETURN;
  if (process.env.MONEO_DESKTOP === "1" && bridge) {
    try {
      const response = await fetch(bridge, {
        method: "POST", headers: { "x-moneo-return": path }, signal: AbortSignal.timeout(10_000),
      });
      if (response.ok) return new Response("<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Return to Moneo</title><body><h1>Continue in Moneo</h1><p>Your connection result is now open in the Moneo app. You can close this browser tab.</p></body></html>", {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "content-security-policy": "default-src 'none'; frame-ancestors 'none'" },
      });
    } catch { /* Keep the connection result accessible if the desktop window cannot open. */ }
  }
  return NextResponse.redirect(new URL(path, request.url), 303);
}
