input.content:
/* Moneo landing page. One monospaced face, flat surfaces, hairline rules, 4px radius on controls,
   0px on containers, ASCII bracket markers, a single dark product mockup (after opencode.ai's
   system), dark first like the app, with Moneo's lime for the main action. */
:root {
  --canvas: #0f1011;
  --surface-soft: #151719;
  --surface-card: #1b1e20;
  --ink: #f3f2ee;
  --body: #c7c6c1;
  --mute: #8f8e89;
  --hairline: rgba(255, 255, 255, 0.10);
  --hairline-strong: #55554f;
  --primary: #cbf26b;
  --primary-ink: #0f1011;
  --primary-press: #b5dc55;
  --mock: #070808;
  --mock-raised: #1b1e20;
  --mock-ink: #f3f2ee;
  --mock-mute: #8f8e89;
  --lime: #cbf26b;
  --violet: #b9a6ff;
  --font: "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --section: 96px;
  color-scheme: dark;
}
@media (prefers-color-scheme: light) {
  :root {
    --canvas: #fdfcfc;
    --surface-soft: #f8f7f7;
    --surface-card: #f1eeee;
    --ink: #201d1d;
    --body: #424245;
    --mute: #646262;
    --hairline: rgba(15, 0, 0, 0.12);
    --hairline-strong: #8a8787;
    --primary: #201d1d;
    --primary-ink: #fdfcfc;
    --primary-press: #0f0000;
    color-scheme: light;
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 72px; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
body {
  margin: 0; background: var(--canvas); color: var(--body);
  font: 400 16px/1.5 var(--font); -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility;
}
a { color: var(--ink); text-underline-offset: 3px; }
b { color: var(--ink); font-weight: 500; }
code { font-family: var(--font); font-size: .92em; color: var(--ink); }
:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }
.wrap { width: 100%; max-width: 1000px; margin: 0 auto; padding: 0 24px; }
.skip { position: absolute; left: -999px; top: 8px; background: var(--ink); color: var(--canvas); padding: 4px 12px; border-radius: 4px; z-index: 20; }
.skip:focus { left: 8px; }
.dim { color: var(--mute); }

/* Nav */
.nav { position: sticky; top: 0; z-index: 10; background: color-mix(in srgb, var(--canvas) 88%, transparent); backdrop-filter: blur(8px); border-bottom: 1px solid var(--hairline); }
.nav-row { display: flex; align-items: center; gap: 24px; height: 56px; }
.brand { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; font-weight: 700; color: var(--ink); letter-spacing: -.01em; }
.brand img { border-radius: 8px; }
.nav nav { display: flex; gap: 20px; margin-left: auto; font-weight: 500; }
.nav nav a { text-decoration: none; color: var(--mute); }
.nav nav a:hover { color: var(--ink); }
.stars { margin-left: 6px; color: var(--mute); }
.stars::before { content: "["; } .stars::after { content: "]"; }

/* Buttons */
.btn { display: inline-flex; align-items: center; gap: 8px; min-height: 40px; padding: 4px 20px; border-radius: 4px; font: 500 16px/2 var(--font); text-decoration: none; border: 1px solid transparent; cursor: pointer; white-space: nowrap; }
.btn-sm { min-height: 34px; padding: 0 14px; font-size: 14px; }
.btn-primary { background: var(--primary); color: var(--primary-ink); }
.btn-primary:hover { background: var(--primary-press); }
.btn-secondary { background: transparent; color: var(--ink); border-color: var(--hairline-strong); }
.btn-secondary:hover { background: var(--surface-soft); }

/* Hero */
.hero { padding-top: 88px; padding-bottom: 48px; }
.badge { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 0 0 28px; font-size: 14px; color: var(--mute); }
.badge a { color: var(--ink); }
.chip { background: var(--lime); color: #0f1011; padding: 0 8px; border-radius: 4px; font-weight: 500; }
h1 { margin: 0; color: var(--ink); font-size: clamp(28px, 4.6vw, 46px); line-height: 1.25; font-weight: 700; letter-spacing: -.02em; }
.lede { max-width: 64ch; margin: 24px 0 0; font-size: 17px; }
.cta-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.meta { margin: 16px 0 0; font-size: 14px; color: var(--mute); }

/* Product mockup: the page's one dark surface */
.mock { background: var(--mock); color: var(--mock-ink); border: 1px solid #23262a; overflow: hidden; }
.mock-bar { display: flex; align-items: center; gap: 16px; padding: 10px 16px; border-bottom: 1px solid #23262a; color: var(--mock-mute); font-size: 13px; }
.dots { display: inline-flex; gap: 6px; } .dots i { width: 10px; height: 10px; border-radius: 50%; background: #2e3236; }
.mock-local { margin-left: auto; color: var(--lime); }
.mock-body { padding: 40px 32px 24px; }
.ascii { margin: 0 0 32px; color: var(--mock-ink); font: 700 clamp(12px, 2.4vw, 20px)/1.15 var(--font); white-space: pre; overflow: hidden; }
.mock-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1px; background: #23262a; border: 1px solid #23262a; margin-bottom: 28px; }
.mock-stat { background: var(--mock); padding: 16px; display: grid; gap: 2px; min-width: 0; }
.mock-stat span { color: var(--mock-mute); font-size: 13px; }
.mock-stat b { color: var(--mock-ink); font-size: clamp(16px, 2.2vw, 22px); font-weight: 700; }
.mock-stat em { font-style: normal; font-size: 13px; color: var(--mock-mute); }
.mock-stat em.up { color: var(--lime); }
.prompt { background: var(--mock-raised); border-radius: 4px; padding: 10px 14px; border-left: 2px solid var(--violet); }
.caret { color: var(--violet); margin-right: 6px; }
.answer { padding: 16px 2px 8px; }
.answer p { margin: 0 0 6px; color: #d9d8d3; }
.answer b { color: var(--lime); font-weight: 700; }
.answer .dim { color: var(--mock-mute); font-size: 14px; }
.tag { display: inline-block; margin-right: 8px; padding: 0 6px; border-radius: 4px; background: #2a2440; color: var(--violet); font-size: 13px; }
.keys { display: flex; flex-wrap: wrap; gap: 24px; margin-top: 20px; color: var(--mock-mute); font-size: 13px; }
kbd { font: inherit; color: var(--mock-ink); margin-right: 6px; }

/* Sections */
.section { padding-top: var(--section); }
.section h2 { margin: 0; padding-bottom: 12px; border-bottom: 1px solid var(--hairline); color: var(--ink); font-size: 16px; font-weight: 700; }
.section-lede { margin: 16px 0 8px; }
.rows { list-style: none; margin: 8px 0 0; padding: 0; }
.rows li { display: grid; grid-template-columns: 3.5ch 15rem minmax(0, 1fr); gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--hairline); }
.rows.compact li { grid-template-columns: 3.5ch minmax(0, 1fr); border-bottom: 0; padding: 6px 0; }
.mark { color: var(--mute); }
.rows li > span:last-child { color: var(--body); }
.note { margin: 16px 0 0; color: var(--mute); font-size: 14px; }

/* Tabs */
.tabs { display: flex; gap: 0; margin-top: 16px; border-bottom: 1px solid var(--hairline-strong); overflow-x: auto; }
.tabs button { background: none; border: 0; border-bottom: 2px solid transparent; margin-bottom: -1px; padding: 8px 16px; font: 500 16px/2 var(--font); color: var(--mute); cursor: pointer; white-space: nowrap; }
.tabs button[aria-selected="true"] { color: var(--ink); border-bottom-color: var(--ink); }
.panel { padding-top: 16px; }
.snippet { position: relative; background: var(--surface-card); border-radius: 4px; }
.snippet pre { margin: 0; padding: 16px 96px 16px 16px; overflow-x: auto; color: var(--ink); line-height: 1.7; }
.copy { position: absolute; top: 10px; right: 10px; background: var(--canvas); color: var(--ink); border: 1px solid var(--hairline-strong); border-radius: 4px; padding: 2px 12px; font: 500 14px/2 var(--font); cursor: pointer; }

/* Downloads */
.downloads { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 1px; background: var(--hairline); border: 1px solid var(--hairline); margin-top: 16px; }
.dl { display: grid; gap: 2px; padding: 16px; background: var(--canvas); text-decoration: none; color: var(--body); }
.dl b::before { content: "↓ "; color: var(--mute); }
.dl span { font-size: 14px; color: var(--mute); }
.dl em { font-style: normal; font-size: 13px; color: var(--mute); min-height: 1.5em; }
.dl:hover { background: var(--surface-soft); }
.dl.recommended { outline: 2px solid var(--primary); outline-offset: -2px; }
.dl.recommended em::after { content: " · for this computer"; color: var(--ink); }
.dl[aria-disabled="true"] { pointer-events: none; opacity: .55; }
.unsigned { margin-top: 20px; border-top: 1px solid var(--hairline); padding-top: 12px; }
.unsigned ul { padding-left: 0; list-style: none; }
.unsigned li { padding: 4px 0; }
.unsigned li::before { content: "[-] "; color: var(--mute); }

/* FAQ and disclosures */
summary { cursor: pointer; list-style: none; color: var(--ink); font-weight: 500; }
summary::-webkit-details-marker { display: none; }
summary::before { content: "+ "; color: var(--mute); }
details[open] > summary::before { content: "− "; }
.faq details { padding: 12px 0; border-bottom: 1px solid var(--hairline); }
.faq p { margin: 8px 0 0 2ch; max-width: 72ch; }

/* Footer */
.footer { margin-top: var(--section); border-top: 1px solid var(--hairline); padding: 0 0 32px; font-size: 14px; }
.footer-links { display: grid; grid-template-columns: repeat(5, 1fr); border-bottom: 1px solid var(--hairline); }
.footer-links a { padding: 16px 8px; text-align: center; color: var(--body); text-decoration: none; border-right: 1px solid var(--hairline); line-height: 2; }
.footer-links a:last-child { border-right: 0; }
.footer-links a:hover { color: var(--ink); }
.footer-meta { display: flex; justify-content: space-between; padding-top: 20px; color: var(--mute); }
.footer-meta a { color: var(--mute); }

@media (max-width: 768px) {
  :root { --section: 64px; }
  .nav nav { display: none; }
  .nav-row .btn { margin-left: auto; }
  .hero { padding-top: 56px; }
  .rows li { grid-template-columns: 3.5ch minmax(0, 1fr); }
  .rows li > span:last-child { grid-column: 2; }
  .mock-grid { grid-template-columns: 1fr; }
  .footer-links { grid-template-columns: repeat(2, 1fr); }
  .footer-links a:nth-child(2n) { border-right: 0; }
  .footer-links a { border-bottom: 1px solid var(--hairline); }
}
@media (max-width: 640px) {
  :root { --section: 48px; }
  .wrap { padding: 0 16px; }
  .mock-body { padding: 24px 16px 16px; }
  .cta-row .btn { flex: 1 1 100%; justify-content: center; }
}

// Moneo landing page: finds the newest published release on GitHub, points every download at its
// installer, and suggests the one for this computer. Without a release (or without the API), the
// links fall back to the releases page.
const REPO = "indkhan/Moneo";
const RELEASES = `https://github.com/${REPO}/releases`;

// Installer names from desktop/electron-builder.config.cjs.
const ASSETS = {
  win: name => /^Moneo-Setup-.*-x64\.exe$/i.test(name),
  "mac-arm": name => /-arm64\.dmg$/i.test(name),
  "mac-intel": name => /-x64\.dmg$/i.test(name),
  appimage: name => /\.AppImage$/i.test(name),
  deb: name => /\.deb$/i.test(name),
};
const LABELS = { win: "Download for Windows", "mac-arm": "Download for Mac", "mac-intel": "Download for Mac (Intel)", appimage: "Download for Linux", deb: "Download for Linux" };

async function platform() {
  const ua = navigator.userAgent;
  const hint = navigator.userAgentData?.platform ?? "";
  if (/Android|iPhone|iPad|iPod/i.test(ua)) return null;
  if (/Win/i.test(hint) || /Windows/i.test(ua)) return "win";
  if (/mac/i.test(hint) || /Macintosh/i.test(ua)) {
    // Chromium can tell Intel from Apple silicon; Safari reports Intel on both, and most Macs today are Apple silicon.
    try {
      const { architecture } = await navigator.userAgentData.getHighEntropyValues(["architecture"]);
      if (architecture === "x86") return "mac-intel";
    } catch { /* not available */ }
    return "mac-arm";
  }
  if (/Linux|X11/i.test(hint + ua)) return "appimage";
  return null;
}

const size = bytes => `${(bytes / 1048576).toFixed(0)} MB`;

async function latestRelease() {
  const response = await fetch(`https://api.github.com/repos/${REPO}/releases/latest`, { headers: { accept: "application/vnd.github+json" } });
  if (response.status === 404) return null;
  if (!response.ok) throw new Error(`GitHub answered ${response.status}`);
  return response.json();
}

async function setUpDownloads() {
  const status = document.querySelector("[data-release-status]");
  const meta = document.querySelector("[data-release-meta]");
  const mine = await platform();
  const cards = [...document.querySelectorAll("[data-asset]")];
  const primary = [...document.querySelectorAll("[data-download-primary]")];
  const label = document.querySelector("[data-download-label]");
  let release = null;
  try { release = await latestRelease(); }
  catch {
    status.innerHTML = `Couldn't reach GitHub just now. All installers are on the <a href="${RELEASES}">releases page</a>.`;
    return;
  }
  if (!release) {
    status.innerHTML = `The first release is on its way. Until then, <a href="#run">run Moneo from source</a> or watch the <a href="${RELEASES}">releases page</a>.`;
    for (const card of cards) { card.href = RELEASES; card.setAttribute("aria-disabled", "true"); }
    return;
  }
  const published = new Date(release.published_at).toLocaleDateString(undefined, { year: "numeric", month: "long", day: "numeric" });
  status.textContent = `Moneo ${release.tag_name}, released ${published}. Free, and your data stays on your computer.`;
  meta.textContent = `${release.tag_name} · Windows · macOS · Linux · MIT licensed`;
  for (const card of cards) {
    const asset = release.assets.find(item => ASSETS[card.dataset.asset](item.name));
    if (!asset) { card.href = release.html_url; continue; }
    card.href = asset.browser_download_url;
    card.querySelector("[data-size]").textContent = `${asset.name} · ${size(asset.size)}`;
    if (card.dataset.asset === mine) {
      card.classList.add("recommended");
      for (const link of primary) link.href = asset.browser_download_url;
      if (label) label.textContent = `${LABELS[mine]} · ${release.tag_name}`;
    }
  }
}

async function showStars() {
  const badge = document.querySelector("[data-stars]");
  try {
    const response = await fetch(`https://api.github.com/repos/${REPO}`);
    if (!response.ok) return;
    const { stargazers_count: stars } = await response.json();
    if (stars > 0) { badge.textContent = stars >= 1000 ? `${(stars / 1000).toFixed(1)}K` : String(stars); badge.hidden = false; }
  } catch { /* optional */ }
}

function setUpTabs() {
  const tabs = [...document.querySelectorAll('[role="tab"]')];
  const select = tab => {
    for (const other of tabs) {
      const on = other === tab;
      other.setAttribute("aria-selected", String(on));
      other.tabIndex = on ? 0 : -1;
      document.getElementById(other.getAttribute("aria-controls")).hidden = !on;
    }
  };
  tabs.forEach((tab, index) => {
    tab.addEventListener("click", () => select(tab));
    tab.addEventListener("keydown", event => {
      const step = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
      if (!step) return;
      const next = tabs[(index + step + tabs.length) % tabs.length];
      select(next);
      next.focus();
    });
  });
  if (location.hash === "#source") select(document.getElementById("tab-source"));
}

function setUpCopy() {
  for (const button of document.querySelectorAll("[data-copy]")) {
    button.addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(button.dataset.copy);
        button.textContent = "Copied";
      } catch { button.textContent = "Select and copy"; }
      setTimeout(() => { button.textContent = "Copy"; }, 2000);
    });
  }
}

setUpTabs();
setUpCopy();
setUpDownloads();
showStars();

