input.content:
/* Moneo landing page. Adapted from opencode.ai's system (flat surfaces, hairline rules, 4px radius
   on controls, monospaced labels) toward a product page: Inter for reading, real screenshots as
   the visuals, dark first like the app, Moneo's lime for the main action. */
:root {
  --canvas: #0f1011;
  --surface: #151719;
  --surface-2: #1b1e20;
  --ink: #f3f2ee;
  --body: #b9b8b3;
  --mute: #85847f;
  --hairline: rgba(255, 255, 255, 0.09);
  --hairline-strong: rgba(255, 255, 255, 0.22);
  --primary: #cbf26b;
  --primary-ink: #0f1011;
  --primary-press: #b5dc55;
  --glow: rgba(203, 242, 107, 0.10);
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --section: 128px;
  color-scheme: dark;
}
@media (prefers-color-scheme: light) {
  :root {
    --canvas: #fbfbf9;
    --surface: #f3f2ee;
    --surface-2: #ebe9e3;
    --ink: #171614;
    --body: #4a4945;
    --mute: #74726c;
    --hairline: rgba(20, 15, 10, 0.10);
    --hairline-strong: rgba(20, 15, 10, 0.25);
    --primary: #171614;
    --primary-ink: #fbfbf9;
    --primary-press: #000;
    --glow: rgba(150, 190, 40, 0.16);
    color-scheme: light;
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 72px; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
body { margin: 0; background: var(--canvas); color: var(--body); font: 400 16px/1.6 var(--sans); -webkit-font-smoothing: antialiased; }
a { color: var(--ink); text-underline-offset: 3px; }
b { color: var(--ink); font-weight: 600; }
code, pre { font-family: var(--mono); }
code { font-size: .88em; color: var(--ink); }
img { display: block; max-width: 100%; height: auto; }
:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }
.wrap { width: 100%; max-width: 1160px; margin: 0 auto; padding: 0 24px; }
.skip { position: absolute; left: -999px; top: 8px; background: var(--ink); color: var(--canvas); padding: 4px 12px; border-radius: 4px; z-index: 20; }
.skip:focus { left: 8px; }
.dim { color: var(--mute); }
.eyebrow { margin: 0 0 12px; font: 500 12px/1.5 var(--mono); letter-spacing: .08em; text-transform: uppercase; color: var(--mute); }

/* Nav */
.nav { position: sticky; top: 0; z-index: 10; background: color-mix(in srgb, var(--canvas) 85%, transparent); backdrop-filter: blur(10px); border-bottom: 1px solid var(--hairline); }
.nav-row { display: flex; align-items: center; gap: 28px; height: 60px; }
.brand { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; font-weight: 600; font-size: 17px; color: var(--ink); }
.brand img { border-radius: 8px; }
.nav nav { display: flex; gap: 24px; margin-left: auto; font-size: 15px; }
.nav nav a { text-decoration: none; color: var(--mute); }
.nav nav a:hover { color: var(--ink); }
.stars { margin-left: 6px; font: 400 13px var(--mono); color: var(--mute); }

/* Buttons */
.btn { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 20px; border-radius: 6px; font: 600 15px/1 var(--sans); text-decoration: none; border: 1px solid transparent; cursor: pointer; white-space: nowrap; }
.btn-sm { min-height: 36px; padding: 0 14px; font-size: 14px; }
.btn-primary { background: var(--primary); color: var(--primary-ink); }
.btn-primary:hover { background: var(--primary-press); }
.btn-secondary { color: var(--ink); border-color: var(--hairline-strong); }
.btn-secondary:hover { background: var(--surface); }

/* Hero */
.hero { padding-top: 104px; padding-bottom: 56px; text-align: center; }
.badge { display: inline-flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 10px; margin: 0 0 28px; padding: 6px 14px 6px 6px; border: 1px solid var(--hairline); border-radius: 999px; font-size: 14px; color: var(--body); }
.badge a { color: var(--ink); text-decoration: none; font-weight: 500; }
.chip { background: #cbf26b; color: #0f1011; padding: 2px 10px; border-radius: 999px; font-weight: 600; font-size: 12px; }
h1 { margin: 0 auto; max-width: 18ch; color: var(--ink); font-size: clamp(36px, 6vw, 68px); line-height: 1.05; font-weight: 700; letter-spacing: -.035em; }
.lede { max-width: 60ch; margin: 24px auto 0; font-size: 18px; }
.cta-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin-top: 36px; }
.meta { margin: 18px 0 0; font: 400 13px var(--mono); color: var(--mute); }

/* Screenshots */
.shot-hero { position: relative; }
.shot-hero::before { content: ""; position: absolute; inset: -40px 10% auto; height: 70%; background: radial-gradient(closest-side, var(--glow), transparent); z-index: -1; }
.frame { margin: 0; border: 1px solid var(--hairline-strong); border-radius: 12px; overflow: hidden; background: #0f1011; box-shadow: 0 30px 80px -30px rgba(0, 0, 0, .55); }
.frame-bar { display: flex; align-items: center; gap: 14px; height: 36px; padding: 0 14px; border-bottom: 1px solid rgba(255,255,255,.08); background: #141618; color: #85847f; font: 400 12px var(--mono); }
.dots { display: inline-flex; gap: 6px; } .dots i { width: 10px; height: 10px; border-radius: 50%; background: #2e3236; }
.caption { margin: 14px 0 0; text-align: center; font: 400 12px var(--mono); color: var(--mute); }

/* Sections */
.section { padding-top: var(--section); }
.section > h2, .closing h2 { margin: 0; max-width: 24ch; color: var(--ink); font-size: clamp(28px, 4vw, 44px); line-height: 1.1; font-weight: 700; letter-spacing: -.03em; }
.section-lede { margin: 16px 0 0; font-size: 17px; max-width: 60ch; }
h3 { margin: 0 0 10px; color: var(--ink); font-size: 22px; line-height: 1.25; font-weight: 600; letter-spacing: -.015em; }

.feature { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: 56px; align-items: center; margin-top: 88px; }
.feature.flip .feature-text { order: 2; }
.feature-text p { margin: 0 0 16px; font-size: 17px; }
.ticks { list-style: none; margin: 0; padding: 0; }
.ticks li { padding: 6px 0 6px 26px; position: relative; font-size: 15px; }
.ticks li::before { content: ""; position: absolute; left: 0; top: 13px; width: 12px; height: 7px; border-left: 2px solid #9fcf3a; border-bottom: 2px solid #9fcf3a; transform: rotate(-45deg); }
.phone-feature { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); }
.phone { margin: 0 auto; width: min(300px, 80%); border: 1px solid var(--hairline-strong); border-radius: 36px; padding: 10px; background: #0b0c0d; box-shadow: 0 30px 80px -30px rgba(0, 0, 0, .55); }
.phone img { border-radius: 28px; }

/* Two ways */
.ways { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 40px; }
.way { border: 1px solid var(--hairline); border-radius: 12px; padding: 28px; background: var(--surface); display: flex; flex-direction: column; align-items: flex-start; gap: 4px; }
.way p { margin: 0 0 12px; }
.way ol { margin: 0 0 20px; padding-left: 20px; }
.way ol li { padding: 3px 0; }
.way .btn { margin-top: auto; }
.snippet { position: relative; width: 100%; background: var(--canvas); border: 1px solid var(--hairline); border-radius: 8px; margin-bottom: 20px; }
.snippet pre { margin: 0; padding: 16px 84px 16px 16px; overflow-x: auto; color: var(--ink); font-size: 14px; line-height: 1.8; }
.copy { position: absolute; top: 10px; right: 10px; background: var(--surface-2); color: var(--ink); border: 1px solid var(--hairline-strong); border-radius: 4px; padding: 4px 12px; font: 500 13px var(--sans); cursor: pointer; }

/* Downloads */
.downloads { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 12px; margin-top: 32px; }
.dl { display: grid; gap: 4px; padding: 20px; border: 1px solid var(--hairline); border-radius: 10px; background: var(--surface); text-decoration: none; color: var(--body); }
.dl b::before { content: "↓  "; color: var(--mute); }
.dl span { font-size: 14px; color: var(--mute); }
.dl em { font-style: normal; font: 400 12px var(--mono); color: var(--mute); min-height: 1.5em; word-break: break-all; }
.dl:hover { border-color: var(--hairline-strong); }
.dl.recommended { border-color: #9fcf3a; box-shadow: 0 0 0 1px #9fcf3a inset; }
.dl.recommended b::after { content: "For this computer"; display: block; margin-top: 4px; font: 500 11px var(--mono); text-transform: uppercase; letter-spacing: .06em; color: #9fcf3a; }
.dl[aria-disabled="true"] { pointer-events: none; opacity: .5; }
.unsigned { margin-top: 24px; }
.unsigned ul { padding-left: 20px; }
.unsigned li { padding: 3px 0; }

/* Privacy cards */
.cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-top: 40px; }
.card { border-top: 1px solid var(--hairline-strong); padding-top: 20px; }
.card h3 { font-size: 17px; }
.card p { margin: 0; font-size: 15px; }

/* FAQ */
summary { cursor: pointer; list-style: none; color: var(--ink); font-weight: 500; font-size: 17px; display: flex; justify-content: space-between; gap: 16px; }
summary::-webkit-details-marker { display: none; }
summary::after { content: "+"; color: var(--mute); font: 400 20px/1 var(--mono); }
details[open] > summary::after { content: "−"; }
.faq { margin-top: 32px; max-width: 820px; }
.faq details { padding: 20px 0; border-bottom: 1px solid var(--hairline); }
.faq p { margin: 10px 0 0; max-width: 70ch; }
.unsigned summary { font-size: 15px; justify-content: flex-start; color: var(--body); }

.closing { text-align: center; }
.closing h2 { margin: 0 auto; }
.center { justify-content: center; }

/* Footer */
.footer { margin-top: var(--section); border-top: 1px solid var(--hairline); padding: 28px 0 40px; font-size: 14px; }
.footer-row { display: flex; flex-wrap: wrap; align-items: center; gap: 24px; }
.footer-row nav { display: flex; flex-wrap: wrap; gap: 20px; margin-left: auto; }
.footer-row nav a { color: var(--mute); text-decoration: none; }
.footer-row nav a:hover { color: var(--ink); }

@media (max-width: 900px) {
  :root { --section: 88px; }
  .nav nav { display: none; }
  .nav-row .btn { margin-left: auto; }
  .feature, .phone-feature { grid-template-columns: 1fr; gap: 28px; margin-top: 64px; }
  .feature.flip .feature-text { order: 0; }
  .ways { grid-template-columns: 1fr; }
  .cards { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 640px) {
  :root { --section: 64px; }
  .wrap { padding: 0 16px; }
  .hero { padding-top: 64px; }
  .wide { display: none; }
  .cta-row .btn { flex: 1 1 100%; justify-content: center; }
  .cards { grid-template-columns: 1fr; }
  .frame { border-radius: 8px; }
  .frame-bar { height: 28px; }
  .footer-row nav { margin-left: 0; }
}

