// Landing-page sample data on top of promo/demo/seed.mjs: an invented person's budgets, goals, a chat with a
// loan card and a Scalable buy card, a voice call with three tasks, artifacts and a Home card.
// Demo database only (port 54422). Run after seed.mjs:  node --env-file=<demo.env> demo-story.mjs
import postgres from "file:///C:/Users/mgsuk/.t3/worktrees/Moneo/t3-bb40520b-1bab67392cb16a35/node_modules/postgres/src/index.js";
import { transform } from "file:///C:/Users/mgsuk/.t3/worktrees/Moneo/t3-bb40520b-1bab67392cb16a35/node_modules/sucrase/dist/esm/index.js";

if (!process.env.SUPABASE_DB_URL?.includes(":54422/")) throw new Error("Refusing: not the demo database.");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [{ id: ws }] = await db`select id from public.workspaces`;
const eur = minor => "€" + (Number(minor) / 100).toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cat = async name => (await db`select id from public.categories where workspace_id=${ws} and name=${name}`)[0].id;
const account = async name => (await db`select id from public.accounts where workspace_id=${ws} and name=${name}`)[0].id;
const ago = minutes => new Date(Date.now() - minutes * 60_000);

await db.begin(async tx => {
  await tx`delete from public.scalable_value_history where workspace_id=${ws}`;
  await tx`delete from public.dashboard_layouts where workspace_id=${ws}`;
  await tx`delete from public.agent_proposals where workspace_id=${ws}`;
  await tx`delete from public.voice_calls where workspace_id=${ws}`;
  await tx`delete from public.messages where workspace_id=${ws}`;
  await tx`delete from public.chat_requests where workspace_id=${ws}`;
  await tx`delete from public.conversations where workspace_id=${ws}`;
  await tx`delete from public.artifacts where workspace_id=${ws}`;

  // The money lent to a friend, for the chat to find.
  const revolut = await account("Revolut");
  const lent = crypto.randomUUID();
  await tx`insert into public.transactions(id,workspace_id,account_id,posted_on,description,amount_minor,currency_code,status,kind)
    values(${lent},${ws},${revolut},'2026-10-14','PayPal *Bilal Ahmed',-25000,'EUR','posted','ordinary')`;

  // Budgets for this month.
  for (const [name, limit] of [["Groceries", 45000], ["Eating out", 25000], ["Going out", 15000], ["Shopping", 20000], ["Transport", 12000]])
    await tx`insert into public.spending_plans(workspace_id,category_id,currency_code,limit_minor) values(${ws},${await cat(name)},'EUR',${limit})`;

  // Goals.
  await tx`delete from public.goals where workspace_id=${ws}`;
  await tx`insert into public.goals(workspace_id,name,target_minor,currency_code,target_date,priority,planned_monthly_minor,contribution_starts_on,recorded_saved_minor,saved_as_of) values
    (${ws},'House deposit',3000000,'EUR','2028-06-30',1,60000,'2026-12-01',1240000,'2026-11-01'),
    (${ws},'Japan in spring',450000,'EUR','2027-04-01',2,40000,'2026-12-01',210000,'2026-11-01'),
    (${ws},'Emergency fund',1200000,'EUR',null,3,0,null,1200000,'2026-11-01')`;

  // A chat: find a loan and record it, then buy more of an ETF.
  const conv = crypto.randomUUID();
  await tx`insert into public.conversations(id,workspace_id,title,created_at) values(${conv},${ws},'Bilal''s loan and an ETF top-up',${ago(12)})`;
  const [ask1, ask2] = [crypto.randomUUID(), crypto.randomUUID()];
  const loan = crypto.randomUUID(), trade = crypto.randomUUID();
  const q1 = "Can you find where I lent money to Bilal and add it, so I don't forget he owes me?";
  const a1 = `Found it. On **14 October** you sent **€250.00** to Bilal Ahmed with PayPal from your Revolut account, and nothing has come back from him since.\n\nAdd it below and it shows in Wealth as money Bilal owes you, and counts in your net worth until he pays you back.\n\n\`\`\`moneo-proposal\n${loan}\n\`\`\``;
  const q2 = "Great. Also buy about €900 of MSCI World on Scalable.";
  const a2 = `Here's the order: **8 shares of iShares Core MSCI World** at about €113.41 each, **€907.28** in total plus a €0.99 order cost, on gettex. Your Scalable cash covers it.\n\nNothing is sent until you tap **Buy**. The price is held for a few minutes.\n\n\`\`\`moneo-proposal\n${trade}\n\`\`\``;
  await tx`insert into public.chat_requests(id,workspace_id,conversation_id,message,status,answer,created_at,updated_at,tool_calls) values
    (${ask1},${ws},${conv},${q1},'completed',${a1},${ago(11)},${ago(11)},${tx.json([{ name: "transactions_search", input: { query: "Bilal" }, output: "1 transaction" }, { name: "finance_detail", input: { id: lent }, output: "PayPal *Bilal Ahmed" }])}),
    (${ask2},${ws},${conv},${q2},'completed',${a2},${ago(9)},${ago(9)},${tx.json([{ name: "investments_portfolio", input: {}, output: "4 holdings" }, { name: "investments_security", input: { query: "MSCI World" }, output: "IE00B4L5Y983" }, { name: "investments_order", input: { side: "buy", amount: "900" }, output: "preview ready" }])})`;
  await tx`insert into public.messages(workspace_id,conversation_id,role,content,request_id,created_at) values
    (${ws},${conv},'user',${q1},${ask1},${ago(11)}), (${ws},${conv},'user',${q2},${ask2},${ago(9)})`;
  await tx`insert into public.messages(workspace_id,conversation_id,role,content,reply_to,created_at) values
    (${ws},${conv},'assistant',${a1},${ask1},${ago(10.8)}), (${ws},${conv},'assistant',${a2},${ask2},${ago(8.8)})`;
  await tx`insert into public.agent_proposals(id,workspace_id,agent,kind,conflict_key,title,detail,evidence,payload,confidence,chat_request_id) values
    (${loan},${ws},'chat','iou_create',${"iou_create:" + loan},'Bilal owes you €250.00','Lent on 14 Oct 2026. Added to Wealth and net worth once you accept.',
     ${tx.json({ transactions: [{ id: lent, date: "2026-10-14", description: "PayPal *Bilal Ahmed", amountMinor: "-25000", currency: "EUR" }] })},
     ${tx.json({ direction: "lent", person: "Bilal Ahmed", amountMinor: "25000", currencyCode: "EUR", date: "2026-10-14" })},100,${ask1})`;
  const expires = new Date(Date.now() + 4 * 3_600_000).toISOString();
  await tx`insert into public.agent_proposals(id,workspace_id,agent,kind,conflict_key,title,detail,evidence,payload,confidence,chat_request_id) values
    (${trade},${ws},'chat','scalable_order',${"scalable_order:" + trade},'Buy 8 × iShares Core MSCI World','Market order · about €907.28 · €0.99 order cost · gettex',
     ${tx.json({ trade: { action: "buy", name: "iShares Core MSCI World", isin: "IE00B4L5Y983", shares: "8", orderType: "market", currencyCode: "EUR", limitPriceMinor: null,
       estimatePriceMinor: "11341", estimatedTotalMinor: "90728", entryCostMinor: "99", exitCostMinor: "99",
       quote: { midMinor: "11240", bidMinor: "11139", askMinor: "11341", at: new Date().toISOString(), outdated: false },
       venue: "gettex", wholePosition: false, warnings: [], expiresAt: expires, brokerUrl: "https://scalable.capital/broker/security?isin=IE00B4L5Y983", kid: null,
       review: "Order review\n\nBuy 8 shares of iShares Core MSCI World (IE00B4L5Y983) at market on gettex." } })},
     ${tx.json({ connectionId: "demo", side: "buy", expiresAt: expires, submission: {} })},100,${ask2})`;

  // A voice call that started three tasks at once.
  const call = crypto.randomUUID(), callConv = crypto.randomUUID();
  await tx`insert into public.conversations(id,workspace_id,title,created_at) values(${callConv},${ws},'Call: trip, subscriptions and Japan',${ago(40)})`;
  const tasks = [
    ["Lisbon trip so far", "How much have I spent on the Lisbon trip so far?", "You've spent **€248.00** on Lisbon so far: the TAP flights on 3 November. Your Travel budget for the year has €1,140 left."],
    ["Subscriptions that went up", "Which of my subscriptions got more expensive this year?", "Two went up this year: **Netflix** from €12.99 to €13.99 in March, and **Spotify** from €10.99 to €11.99 in June. Together that's €24 more a year."],
    ["Japan goal check", "Am I on track to save for Japan by April?", "Yes. You have **€2,100** of €4,500. At €400 a month from December you reach it on **1 April 2027**, right on time."],
  ].map(([title, text, answer]) => ({ id: crypto.randomUUID(), title, text, answer }));
  for (const [index, task] of tasks.entries()) {
    const at = ago(39 - index);
    await tx`insert into public.chat_requests(id,workspace_id,conversation_id,message,status,answer,created_at,updated_at,context) values
      (${task.id},${ws},${callConv},${task.text},'completed',${task.answer},${at},${at},${tx.json({ input: "voice" })})`;
    await tx`insert into public.messages(workspace_id,conversation_id,role,content,request_id,context,created_at) values(${ws},${callConv},'user',${task.text},${task.id},${tx.json({ input: "voice" })},${at})`;
    await tx`insert into public.messages(workspace_id,conversation_id,role,content,reply_to,created_at) values(${ws},${callConv},'assistant',${task.answer},${task.id},${ago(38.5 - index)})`;
  }
  await tx`insert into public.voice_calls(id,workspace_id,conversation_id,duration_seconds,transcript,tasks,summary,summary_status,request_ids,created_at) values
    (${call},${ws},${callConv},214,${tx.json([
      { role: "user", text: "Hey, three things. How much has Lisbon cost me so far, which subscriptions got more expensive, and am I on track for Japan?" },
      { role: "assistant", text: "On it. I'm checking all three at once. Lisbon first: €248 so far, just the flights." },
      { role: "assistant", text: "Netflix and Spotify both went up a euro this year. And Japan is on track for April if you keep €400 a month going." },
      { role: "user", text: "Perfect, thanks." }])},
     ${tx.json(tasks.map(task => ({ requestId: task.id, text: task.text, title: task.title, status: "done" })))},
     ${"- Lisbon so far: €248.00, only the flights\n- Netflix and Spotify each went up €1 a month this year\n- Japan: €2,100 of €4,500, on track for 1 April 2027"},'done',
     ${tasks.map(task => task.id)},${ago(40)})`;

  // Artifacts: the monthly story page, plus a Home card made from one.
  const html = (await import("node:fs")).readFileSync(new URL("./artifact-story.html", import.meta.url), "utf8");
  const ids = {};
  for (const [title, prompt] of [["Monthly money story", "Build a monthly money story for October"], ["Eating out tracker", "Track my eating out against my budget and show it on Home"], ["Subscription radar", "Find my subscriptions and what they cost a year"]]) {
    const [{ id }] = await tx`insert into public.artifacts(workspace_id,title) values(${ws},${title}) returning id`;
    await tx`insert into public.artifact_versions(workspace_id,artifact_id,version,prompt,html,queries,model) values(${ws},${id},1,${prompt},${html.replace("Monthly money story", title)},'[]','gpt-5.1')`;
    ids[title] = id;
  }
  const [{ spent, visits }] = await tx`select coalesce(-sum(amount_minor),0)::bigint as spent, count(*)::int as visits from public.transactions
    where workspace_id=${ws} and category_id=${await cat("Eating out")} and posted_on>='2026-11-01'`;
  const places = await tx`select m.name, -sum(t.amount_minor)::bigint as minor from public.transactions t join public.merchants m on m.id=t.merchant_id
    where t.workspace_id=${ws} and t.category_id=${await cat("Eating out")} and t.posted_on>='2026-11-01' group by 1 order by 2 desc limit 3`;
  const pct = Math.round(Number(spent) / 25000 * 100);
  const source = `export default function Card({ size }) {
  const places = ${JSON.stringify(places.map(row => [row.name, eur(row.minor)]))};
  return <div className="flex h-full flex-col gap-3">
    <div className="flex items-baseline justify-between gap-3"><p className="eyebrow">Eating out · November</p><p className="text-sm text-muted-foreground">${visits} visits</p></div>
    <p className="font-display text-4xl font-semibold tracking-tight tabular-nums">${eur(spent)} <span className="text-base font-normal text-muted-foreground">of €250.00</span></p>
    <div style={{ height: 8, borderRadius: 999, background: "var(--color-muted)" }}><div style={{ width: "${pct}%", height: 8, borderRadius: 999, background: "var(--color-primary)" }} /></div>
    <p className="text-sm text-muted-foreground">${pct}% used with 17 days to go · on track</p>
    {size !== "S" && <div className="mt-1 grid gap-1.5">{places.map(([name, amount]) => <div key={name} className="flex justify-between text-sm"><span>{name}</span><span className="tabular-nums">{amount}</span></div>)}</div>}
  </div>;
}`;
  const compiled = transform(source, { transforms: ["typescript", "jsx", "imports"], jsxPragma: "h", jsxFragmentPragma: "Fragment", production: true }).code;
  const [{ id: card }] = await tx`insert into public.artifact_cards(workspace_id,artifact_id,title,size,published_version) values(${ws},${ids["Eating out tracker"]},'Eating out',${"M"},1) returning id`;
  await tx`insert into public.artifact_card_versions(workspace_id,card_id,version,kind,source,compiled,queries,params,prompt,model) values(${ws},${card},1,'code',${source},${compiled},'[]','[]','A Home card for eating out this month against my budget','gpt-5.1')`;
  await tx`insert into public.dashboard_layouts(workspace_id,items) values(${ws},${["overview", `card:${card}`, "budgets", "upcoming", "goals", "spending", "accounts"]})`;
  console.log(JSON.stringify({ chat: conv, call: callConv, artifact: ids["Monthly money story"], card, lent }));
});
await db.end();

