S="$LOCALAPPDATA/Temp/claude/cc74f73eb1c8553d/28aef71f-9e06-47a2-8c12-737fd8108d95/scratchpad"; cat > $S/demo-history.mjs <<'EOF'
// A year of Scalable portfolio value before the first sync, so net worth reads as a continuous history (demo database only).
import postgres from "file:///C:/Users/mgsuk/.t3/worktrees/Moneo/t3-bb40520b-1bab67392cb16a35/node_modules/postgres/src/index.js";
if (!process.env.SUPABASE_DB_URL?.includes(":54422/")) throw new Error("Refusing: not the demo database.");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 2, onnotice: () => {} });
const [{ id: ws }] = await db`select id from public.workspaces`;
const [{ total }] = await db`select sum(amount_minor)::bigint as total from public.wealth_items where workspace_id=${ws}`;
let seed = 7; const rnd = () => (seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296;
const start = Date.UTC(2025, 10, 1), end = Date.UTC(2026, 10, 12), days = Math.round((end - start) / 86_400_000);
const final = Number(total) / 100, contributions = 12_000, gain = 18_640.3, base = final - contributions - gain;
const rows = []; let noise = 0, crypto = 4_100;
for (let i = 0; i <= days; i++) {
  const date = new Date(start + i * 86_400_000), t = i / days;
  const deposits = 1000 * (Math.floor((date.getUTCFullYear() - 2025) * 12 + date.getUTCMonth() - 10) + (date.getUTCDate() >= 28 ? 1 : 0));
  // Steady growth with a spring dip and recovery, plus day-to-day wobble that fades at the end.
  const path = gain * (t + 0.06 * Math.sin(Math.PI * t * 2.2) - 0.07 * Math.exp(-((t - 0.42) ** 2) / 0.004));
  noise = noise * 0.9 + (rnd() - 0.5) * 900; crypto = Math.max(2500, crypto + (rnd() - 0.47) * 120);
  const cryptoNow = crypto + (6620.4 - crypto) * t ** 4;
  const totalNow = base + Math.max(0, deposits) + path + noise * (1 - t);
  const tm = Math.round(totalNow * 100), cm = Math.round(cryptoNow * 100), cash = 500000;
  rows.push({ workspace_id: ws, on_date: date.toISOString().slice(0, 10), currency_code: "EUR", securities_minor: tm - cm - cash, crypto_minor: cm, cash_minor: cash, total_minor: tm });
}
await db`delete from public.scalable_value_history where workspace_id=${ws}`;
await db`insert into public.scalable_value_history ${db(rows)}`;
await db`update public.scalable_connections set history_status='ok', history_checked_on=current_date where workspace_id=${ws}`;
console.log(`history ${rows[0].on_date} ${rows[0].total_minor} → ${rows.at(-1).on_date} ${rows.at(-1).total_minor}; synced ${total}`);
await db.end();
EOF
node --env-file="$S/demo/run/demo.env" $S/demo-history.mjs 2>&1 | grep -v -i warn

